CREATE TYPE "AiRequestStatus" AS ENUM ('QUEUED', 'RUNNING', 'SUCCEEDED', 'FAILED', 'CANCELLED');
CREATE TYPE "AiLedgerEntryType" AS ENUM ('CREDIT_PURCHASE', 'CREDIT_GRANT', 'CREDIT_RESERVATION', 'CREDIT_CONSUMPTION', 'CREDIT_RELEASE', 'CREDIT_REFUND', 'ADMIN_ADJUSTMENT');
CREATE TYPE "AiMessageRole" AS ENUM ('USER', 'ASSISTANT', 'SYSTEM');

CREATE TABLE "AiProvider" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "key" TEXT NOT NULL, "displayName" TEXT NOT NULL, "isEnabled" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AiProvider_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiModel" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "providerId" UUID NOT NULL, "key" TEXT NOT NULL, "displayName" TEXT NOT NULL, "capabilities" JSONB NOT NULL, "isEnabled" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AiModel_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiConversation" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "title" TEXT NOT NULL DEFAULT 'New conversation', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AiConversation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiMessage" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "conversationId" UUID NOT NULL, "role" "AiMessageRole" NOT NULL, "content" TEXT NOT NULL, "provider" TEXT, "model" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiGenerationJob" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "feature" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "status" "AiRequestStatus" NOT NULL DEFAULT 'QUEUED', "requestedModel" TEXT, "input" JSONB NOT NULL, "output" JSONB, "errorCode" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "startedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), CONSTRAINT "AiGenerationJob_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiWebsiteProject" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "status" TEXT NOT NULL DEFAULT 'DRAFT', "schema" JSONB NOT NULL, "schemaVersion" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AiWebsiteProject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiWebsiteRevision" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "projectId" UUID NOT NULL, "version" INTEGER NOT NULL, "schema" JSONB NOT NULL, "createdById" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiWebsiteRevision_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiCreditWallet" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "balance" INTEGER NOT NULL DEFAULT 0, "reserved" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AiCreditWallet_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiCreditLedger" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "walletId" UUID NOT NULL, "userId" UUID NOT NULL, "type" "AiLedgerEntryType" NOT NULL, "amount" INTEGER NOT NULL, "idempotencyKey" TEXT NOT NULL, "referenceType" TEXT, "referenceId" TEXT, "note" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiCreditLedger_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiUsageRecord" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "providerId" UUID, "modelId" UUID, "feature" TEXT NOT NULL, "inputTokens" INTEGER, "outputTokens" INTEGER, "providerCost" INTEGER, "creditsConsumed" INTEGER NOT NULL DEFAULT 0, "status" "AiRequestStatus" NOT NULL, "isEstimated" BOOLEAN NOT NULL DEFAULT false, "executionMs" INTEGER, "providerRequestId" TEXT, "idempotencyKey" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiUsageRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiSafetyEvent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID, "eventType" TEXT NOT NULL, "severity" TEXT NOT NULL, "details" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiSafetyEvent_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "AiProvider_key_key" ON "AiProvider"("key");
CREATE UNIQUE INDEX "AiModel_providerId_key_key" ON "AiModel"("providerId", "key");
CREATE INDEX "AiModel_isEnabled_idx" ON "AiModel"("isEnabled");
CREATE INDEX "AiConversation_userId_updatedAt_idx" ON "AiConversation"("userId", "updatedAt");
