CREATE UNIQUE INDEX "AiCreditWallet_userId_key" ON "AiCreditWallet"("userId");
CREATE UNIQUE INDEX "AiCreditLedger_idempotencyKey_key" ON "AiCreditLedger"("idempotencyKey");
CREATE INDEX "AiCreditLedger_userId_createdAt_idx" ON "AiCreditLedger"("userId", "createdAt");
CREATE INDEX "AiCreditLedger_referenceType_referenceId_idx" ON "AiCreditLedger"("referenceType", "referenceId");
CREATE UNIQUE INDEX "AiUsageRecord_idempotencyKey_key" ON "AiUsageRecord"("idempotencyKey");
CREATE INDEX "AiUsageRecord_userId_createdAt_idx" ON "AiUsageRecord"("userId", "createdAt");
CREATE INDEX "AiUsageRecord_feature_status_createdAt_idx" ON "AiUsageRecord"("feature", "status", "createdAt");
CREATE INDEX "AiSafetyEvent_eventType_createdAt_idx" ON "AiSafetyEvent"("eventType", "createdAt");
CREATE INDEX "AiSafetyEvent_userId_createdAt_idx" ON "AiSafetyEvent"("userId", "createdAt");

ALTER TABLE "AiModel" ADD CONSTRAINT "AiModel_providerId_fkey" FOREIGN KEY ("providerId") REFERENCES "AiProvider"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiConversation" ADD CONSTRAINT "AiConversation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
