ALTER TABLE "AiWebsiteRevision" ADD CONSTRAINT "AiWebsiteRevision_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
